args.query:
\dt api.*
\dv api.*
select * from api.app_user;
select * from api.company;
select grantee, table_name, privilege_type from information_schema.table_privileges where table_schema='api' order by 2,1;
select tablename, policyname, roles, cmd, qual, with_check from pg_policies;
select relname, relrowsecurity, relforcerowsecurity from pg_class where relnamespace='api'::regnamespace and relkind in ('r','v');
\d api.application

\d api.company
\d api.status
select * from api.status;
select a.id,number,company_id,status_id,amount from api.application a order by 1;
select proname, prosecdef from pg_proc where pronamespace in ('priv'::regnamespace);
select pg_get_functiondef('priv.my_company'::regproc);
select tgname, tgrelid::regclass from pg_trigger where not tgisinternal;

create table api.contract(
 id serial primary key,
 number text not null unique,
 application_id int not null references api.application(id),
 amount numeric not null check (amount>0),
 signed_on date,
 status text not null default 'Проект' check (status in ('Проект','Подписан')));
create index on api.contract(application_id);
create function priv.check_contract() returns trigger language plpgsql security definer set search_path=api as $$
begin
 if not exists (select 1 from api.application where id=new.application_id and status_id=priv.status_id('Одобрена')) then
  raise exception 'Договор можно заключить только по одобренной заявке';
 end if;
 return new; end $$;
create trigger check_contract before insert or update on api.contract for each row execute function priv.check_contract();
alter table api.contract enable row level security;
create policy admin_all on api.contract for all to fund_admin using(true) with check(true);
create policy lawyer_all on api.contract for all to lawyer using(true) with check(true);
create policy applicant_read on api.contract for select to applicant using (exists(select 1 from api.application a where a.id=application_id and a.company_id=priv.my_company()));
grant select,insert,update,delete on api.contract to fund_admin, lawyer;
grant select on api.contract to applicant;
grant usage on sequence api.contract_id_seq to fund_admin, lawyer;
grant select on api.application, api.company, api.status to lawyer;
create policy lawyer_read on api.application for select to lawyer using(true);
grant usage on schema api to lawyer;
alter table api.company add column ref_key uuid unique;
update api.app_user set role='lawyer' where login='lawyer1';
create view api.limit_balance with (security_invoker=true) as
select c.name as company, c.funding_limit, ap.approved, coalesce(ct.contracted,0) as contracted, c.funding_limit-coalesce(ct.contracted,0) as remaining
from api.company c
join (select company_id, sum(amount) approved from api.application where status_id=priv.status_id('Одобрена') group by 1) ap on ap.company_id=c.id
left join (select a.company_id, sum(k.amount) contracted from api.contract k join api.application a on a.id=k.application_id group by 1) ct on ct.company_id=c.id;
grant select on api.limit_balance to fund_admin, lawyer, applicant;
select rolname from pg_roles where rolname in ('lawyer','authenticator');
select grantee,privilege_type from information_schema.table_privileges where table_name='status' and grantee='lawyer';
